metadata.rules_text:
{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is negative or shows early negative momentum.",
    "Increase forecast slightly after a sharp spike in price if sentiment remains neutral or positive.",
    "Apply mean reversion bias for forecasts that deviate >10% from recent 7-day average, especially if sentiment is flat.",
    "Reduce forecast overshoot after spikes by 10-15% if sentiment is weak or shows cooling.",
    "Increase forecast sensitivity to sentiment shifts in the last 5 days — especially if sentiment turns positive after a dip.",
    "Avoid over-optimism in short-term (1-3 day) forecasts when sentiment is volatile or mixed."
  ]
}
